# ------------------------------------------------------------
# 3. Helper functions
# ------------------------------------------------------------

as_bool <- function(
    x
) {
  
  if (
    is.logical(
      x
    )
  ) {
    return(
      x
    )
  }
  
  
  x_character <- toupper(
    trimws(
      as.character(
        x
      )
    )
  )
  
  
  output <- rep(
    NA,
    length(
      x_character
    )
  )
  
  
  output[
    x_character %in%
      c(
        "TRUE",
        "T",
        "1"
      )
  ] <- TRUE
  
  
  output[
    x_character %in%
      c(
        "FALSE",
        "F",
        "0"
      )
  ] <- FALSE
  
  
  if (
    anyNA(
      output
    )
  ) {
    stop(
      "Could not safely convert a logical field."
    )
  }
  
  
  output
}


# ------------------------------------------------------------
# Adjusted Rand Index
# ------------------------------------------------------------
#
# Implemented directly so the reproducibility check does not
# depend on an additional package.
#
# ------------------------------------------------------------

adjusted_rand_index <- function(
    x,
    y
) {
  
  if (
    length(x) !=
    length(y)
  ) {
    stop(
      "ARI vectors have different lengths."
    )
  }
  
  
  contingency <- table(
    x,
    y
  )
  
  
  choose2 <- function(
    z
  ) {
    
    z *
      (
        z - 1
      ) /
      2
  }
  
  
  sum_cells <- sum(
    choose2(
      contingency
    )
  )
  
  
  row_sums <- rowSums(
    contingency
  )
  
  
  col_sums <- colSums(
    contingency
  )
  
  
  sum_rows <- sum(
    choose2(
      row_sums
    )
  )
  
  
  sum_cols <- sum(
    choose2(
      col_sums
    )
  )
  
  
  n <- sum(
    contingency
  )
  
  
  total_pairs <- choose2(
    n
  )
  
  
  expected_index <-
    (
      sum_rows *
        sum_cols
    ) /
    total_pairs
  
  
  max_index <-
    0.5 *
    (
      sum_rows +
        sum_cols
    )
  
  
  denominator <-
    max_index -
    expected_index
  
  
  if (
    abs(
      denominator
    ) <
    .Machine$double.eps
  ) {
    
    return(
      1
    )
  }
  
  
  (
    sum_cells -
      expected_index
  ) /
    denominator
}

# ------------------------------------------------------------
# Helper to add one observed control
# ------------------------------------------------------------

actual_rows <- list()


add_control <- function(
    block,
    metric,
    actual
) {
  
  if (
    length(actual) != 1L
  ) {
    stop(
      "Control ",
      block,
      "/",
      metric,
      " did not produce a scalar value."
    )
  }
  
  
  if (
    is.na(actual) ||
    !is.finite(actual)
  ) {
    stop(
      "Control ",
      block,
      "/",
      metric,
      " produced an invalid value."
    )
  }
  
  
  actual_rows[[length(actual_rows) + 1L]] <<- data.frame(
    
    block = block,
    
    metric = metric,
    
    actual = as.numeric(actual),
    
    stringsAsFactors = FALSE
  )
  
  
  invisible(NULL)
}
