extract_sensitivity <- function(
    scenario,
    prefix
) {
  
  x <- sensitivity[
    sensitivity$escenario ==
      scenario,
  ]
  
  
  if (
    nrow(
      x
    ) !=
    n_expected_units
  ) {
    stop(
      "Sensitivity scenario ",
      scenario,
      " does not contain ",
      n_expected_units,
      " units."
    )
  }
  
  
  add_control(
    "sensitivity",
    paste0(
      prefix,
      "_MAP_changes"
    ),
    sum(
      !x$MAP_estable
    )
  )
  
  
  add_control(
    "sensitivity",
    paste0(
      prefix,
      "_median_JS"
    ),
    median(
      x$distancia_JS,
      na.rm = TRUE
    )
  )
  
  
  add_control(
    "sensitivity",
    paste0(
      prefix,
      "_median_delta_H"
    ),
    median(
      x$delta_entropia,
      na.rm = TRUE
    )
  )
}


