  nrow(
    actual
  ) !=
  44L
) {
  stop(
    "Expected 44 observed controls; calculated ",
    nrow(
      actual
    ),
    "."
  )
}


if (
  anyDuplicated(
    actual[
      ,
      c(
        "block",
        "metric"
      )
    ]
  )
) {
  stop(
    "Duplicated observed controls."
  )
}


# ============================================================
# 12. MATCH EXPECTED AND OBSERVED RESULTS
# ============================================================

comparison <- merge(
  expected,
  actual,
  by = c(
    "block",
    "metric"
  ),
  all = TRUE,
  sort = FALSE
)


if (
  nrow(
    comparison
  ) !=
  44L
) {
  stop(
    "Expected and observed controls do not match one-to-one."
  )
}


if (
  anyNA(
    comparison$expected
  ) ||
  anyNA(
    comparison$actual
  )
) {
  stop(
    paste0(
      "At least one expected control has no observed counterpart, ",
      "or vice versa."
    )
  )
}


# Restore expected-results order

comparison$order_expected <- match(
  paste(
    comparison$block,
    comparison$metric,
    sep = "::"
  ),
  paste(
    expected$block,
    expected$metric,
    sep = "::"
  )
)


comparison <- comparison[
  order(
    comparison$order_expected
  ),
]


comparison$order_expected <- NULL


# ============================================================
# 13. CALCULATE DIFFERENCES AND PASS/FAIL
# ============================================================

comparison$absolute_difference <- abs(
  comparison$actual -
    comparison$expected
)


comparison$pass <-
  comparison$absolute_difference <=
  comparison$tolerance


comparison$status <- ifelse(
  comparison$pass,
  "PASS",
  "FAIL"
)


# ============================================================
# 14. WRITE CHECK REPORT
# ============================================================

report_file <- here::here(
  "checks",
  "reproducibility_report.csv"
)


write.csv(
  comparison[
    ,
    c(
      "block",
      "metric",
      "expected",
      "actual",
      "absolute_difference",
      "tolerance",
      "status"
    )
  ],
  report_file,
  row.names = FALSE,
  fileEncoding = "UTF-8"
)


# ============================================================
