)

cat(
  "============================================\n\n"
)


display_table <- comparison[
  ,
  c(
    "block",
    "metric",
    "expected",
    "actual",
    "absolute_difference",
    "tolerance",
    "status"
  )
]


print(
  display_table,
  row.names = FALSE,
  digits = 10
)


n_pass <- sum(
  comparison$pass
)


n_fail <- sum(
  !comparison$pass
)


cat(
  "\n--------------------------------------------\n"
)

cat(
  "Controls passed: ",
  n_pass,
  " / ",
  nrow(
    comparison
  ),
  "\n",
  sep = ""
)


cat(
  "Controls failed: ",
  n_fail,
  "\n",
  sep = ""
)


cat(
  "Report: checks/reproducibility_report.csv\n"
)

cat(
  "--------------------------------------------\n"
)


# ============================================================
# 16. FINAL RESULT
# ============================================================

if (
  n_fail > 0L
) {
  
  failed_controls <- comparison[
    !comparison$pass,
    c(
      "block",
      "metric",
      "expected",
      "actual",
      "absolute_difference",
      "tolerance"
    )
  ]
  
  
  cat(
    "\nFAILED CONTROLS:\n\n"
  )
  
  
  print(
    failed_controls,
    row.names = FALSE,
    digits = 12
  )
  
  
  cat(
    "\n============================================\n\n"
  )
  
  
  stop(
    paste0(
      "Reproducibility check FAILED: ",
      n_fail,
      " of ",
      nrow(
        comparison
      ),
      " controls differ from the verified baseline."
    )
  )
}


cat(
  "\nAll verified analytical and spatial controls match ",
  "the reference baseline.\n",
  sep = ""
)


cat(
  "These checks confirm computational reproducibility of the ",
  "specified outputs; they do not constitute external model validation.\n"
)


cat(
  "============================================\n\n"
)


message(
  "check_reproducibility.R completed successfully."
)

message(
  "44 / 44 controls passed."
